<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{useDisplay}from'vuetify';import{useI18n}from'vue-i18n';import{salesApi}from '@/api/sales';import{customersApi}from '@/api/customers';import{productsApi}from '@/api/products';import{useApiError}from '@/composables/useApiError';import type{LostSale}from '@/types/sales';import type{Customer,Product}from '@/types/models';
const{t}=useI18n(),{mdAndUp}=useDisplay(),error=useApiError(),loading=ref(false),saving=ref(false),dialog=ref(false),rows=ref<LostSale[]>([]),customers=ref<Customer[]>([]),products=ref<Product[]>([]);const form=reactive({companyId:null as number|null,branchId:null as number|null,customerId:null as number|null,productId:null as number|null,reasonCode:'PRICE',notes:'',expectedAmount:0});
const money=(v:number)=>new Intl.NumberFormat().format(v||0);async function load(){loading.value=true;try{rows.value=(await salesApi.lostSales({size:100})).content}catch(e){error.set(e)}finally{loading.value=false}}async function open(){dialog.value=true;try{const[c,p]=await Promise.all([customersApi.list({size:100}),productsApi.list({size:100})]);customers.value=c.content;products.value=p.content}catch(e){error.set(e)}}async function save(){if(!form.companyId||!form.branchId)return;saving.value=true;try{await salesApi.recordLostSale({companyId:form.companyId,branchId:form.branchId,customerId:form.customerId||undefined,productId:form.productId||undefined,reasonCode:form.reasonCode,notes:form.notes||undefined,expectedAmount:form.expectedAmount});dialog.value=false;Object.assign(form,{companyId:null,branchId:null,customerId:null,productId:null,reasonCode:'PRICE',notes:'',expectedAmount:0});await load()}catch(e){error.set(e)}finally{saving.value=false}}onMounted(load);
</script>
<template><section aria-labelledby="lost-sales-title"><div class="d-flex align-center mb-4"><div><h2 id="lost-sales-title" class="text-h6">{{t('sales.lostSales')}}</h2><p class="text-body-2 text-medium-emphasis mb-0">{{t('sales.lostSalesSubtitle')}}</p></div><v-spacer/><v-btn color="primary" prepend-icon="mdi-plus" @click="open">{{t('sales.recordLostSale')}}</v-btn></div><v-alert v-if="error.message.value" type="error" closable class="mb-4" @click:close="error.clear()">{{error.message.value}}</v-alert><v-skeleton-loader v-if="loading" type="article@3"/><v-card v-else rounded="xl" class="app-data-surface"><v-table v-if="mdAndUp&&rows.length"><thead><tr><th>{{t('sales.reason')}}</th><th>{{t('sales.customer')}}</th><th>{{t('sales.product')}}</th><th>{{t('sales.expectedAmount')}}</th><th>{{t('sales.createdAt')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{t(`sales.values.${row.reasonCode}`,row.reasonCode)}}</td><td>{{row.customerId||'—'}}</td><td>{{row.productId||'—'}}</td><td>{{money(row.expectedAmount)}}</td><td>{{new Date(row.occurredAt).toLocaleString()}}</td></tr></tbody></v-table><div v-else-if="rows.length" class="pa-3"><v-card v-for="row in rows" :key="row.id" variant="outlined" rounded="lg" class="pa-4 mb-3"><div class="d-flex"><strong>{{t(`sales.values.${row.reasonCode}`,row.reasonCode)}}</strong><v-spacer/>{{money(row.expectedAmount)}}</div><div class="text-body-2 text-medium-emphasis mt-2">{{row.notes||t('sales.noNotes')}}</div></v-card></div><div v-else class="pa-10 text-center text-medium-emphasis">{{t('sales.noLostSales')}}</div></v-card>
<v-dialog v-model="dialog" :fullscreen="!mdAndUp" max-width="720"><v-card rounded="xl"><v-toolbar color="transparent"><v-toolbar-title>{{t('sales.recordLostSale')}}</v-toolbar-title><v-btn icon="mdi-close" @click="dialog=false"/></v-toolbar><v-card-text><v-row><v-col cols="6"><v-text-field v-model.number="form.companyId" type="number" min="1" :label="t('sales.company')"/></v-col><v-col cols="6"><v-text-field v-model.number="form.branchId" type="number" min="1" :label="t('sales.branch')"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.customerId" clearable :items="customers" item-title="displayName" item-value="id" :label="t('sales.customer')"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.productId" clearable :items="products" item-title="name" item-value="id" :label="t('sales.product')"/></v-col><v-col cols="12" md="6"><v-select v-model="form.reasonCode" :items="['PRICE','OUT_OF_STOCK','COMPETITOR','PAYMENT_TERMS','CUSTOMER_CANCELLED','OTHER']" :item-title="(v:string)=>t(`sales.values.${v}`,v)" :label="t('sales.reason')"/></v-col><v-col cols="12" md="6"><v-text-field v-model.number="form.expectedAmount" type="number" min="0" :label="t('sales.expectedAmount')"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" :label="t('sales.notes')"/></v-col></v-row></v-card-text><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="dialog=false">{{t('common.cancel')}}</v-btn><v-btn color="primary" :loading="saving" :disabled="!form.companyId || !form.branchId || !form.reasonCode" @click="save">{{t('common.save')}}</v-btn></v-card-actions></v-card></v-dialog>
</section></template>
<style scoped>@media(max-width:599px){:deep(.v-btn){min-height:44px}}</style>
